<?php namespace App\Models; use Illuminate\Foundation\Auth\User as Authenticatable; use Illuminate\Notifications\Notifiable; class User extends Authenticatable{use Notifiable; protected $fillable=['name','email','password','active_tenant_id']; protected $hidden=['password','remember_token']; public function tenants(){return $this->belongsToMany(Tenant::class);} public function activeTenant(){return $this->belongsTo(Tenant::class,'active_tenant_id');}}
